import {fireEvent,render,screen,waitFor} from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import {afterEach,describe,expect,it,vi} from 'vitest'
import {SurveyBuilder} from './SurveyBuilder'
import {ResearchIssueList} from './ResearchIssueList'
import {authoringIssueTarget} from './authoring-issue-location'
import type {ResearchDraft} from './builder.types'
import fixture from './test-fixtures/s04-import-failure-sources.json'

const prefix='/api/survey/projects/p1',draft=fixture.draft as ResearchDraft
// Generated by the separately executed real backend assertions, retained with
// source hashes. Frontend-only CI need not install backend dependencies.
function mountBuilder(){
  const fetcher=vi.fn(async(url:string,init?:RequestInit)=>{
    let data:unknown
    if(url===prefix+'/instruments?page=1')data={list:[draft]}
    else if(url===prefix+'/assets')data={assets:[]}
    else if(url===prefix+'/catalog?page=1')data={list:[]}
    else if(url===prefix+'/instruments/scale')data=draft
    else if(url==='/api/survey/auth/csrf')data={csrfToken:'synthetic'}
    else if(url===prefix+'/instruments/scale/bulk-import/preview'){
      const batch=JSON.parse(init!.body as string),actual=fixture.cases.find(c=>c.csv===batch.content)
      expect(batch.format).toBe('CSV');expect(actual).toBeDefined();data={revision:1,...actual!.result}
    }
    else throw Error('Unexpected route '+url)
    return {ok:true,json:async()=>({code:0,data})} as Response
  })
  vi.stubGlobal('fetch',fetcher);render(<SurveyBuilder projectId="p1"/>);return fetcher
}
afterEach(()=>{vi.restoreAllMocks();vi.unstubAllGlobals()})
describe('S04 import locations from actual server failure sources',()=>{
  it.each(fixture.cases)('selects the correct input record for $name',async({csv,rawLine,sourceLine,label,selected,result:actual})=>{
    expect(actual.ok).toBe(false);expect(actual.issues[0].line).toBe(rawLine)
    expect(authoringIssueTarget(draft,actual.issues[0],{format:'CSV',content:csv,items:actual.items})).toMatchObject({line:sourceLine})
    const user=userEvent.setup(),fetcher=mountBuilder()
    fireEvent.click(await screen.findByRole('button',{name:/合成量表 SCALE/}))
    fireEvent.change(await screen.findByLabelText('输入格式'),{target:{value:'CSV'}})
    const input=screen.getByLabelText('待解析的导入内容') as HTMLTextAreaElement
    fireEvent.change(input,{target:{value:csv}})
    fireEvent.click(screen.getByRole('button',{name:'解析并预览（不保存）'}))
    const location=await screen.findByRole('button',{name:label+'：'+actual.issues[0].message})
    location.focus();await user.keyboard('{Enter}')
    await waitFor(()=>expect(input).toHaveFocus())
    expect(input.value.slice(input.selectionStart,input.selectionEnd)).toBe(selected)
    expect(input.selectionStart).toBeGreaterThan(csv.indexOf('\n'))
    expect(screen.queryByRole('button',{name:'确认导入全部题目'})).toBeNull()
    expect(fetcher.mock.calls.some(([url,init])=>url.endsWith('/apply')||init?.method==='PATCH')).toBe(false)
  })
  it('does not pretend a general apply line:1 or unknown source is an exact input line',()=>{
    const {batch,candidate,issues}=fixture.general
    expect(candidate.ok).toBe(true)
    expect(issues).toEqual([{line:1,message:'预览数据已发生变化，请重新预览'}])
    const context={format:'CSV' as const,content:batch.content,items:candidate.items},onLocate=vi.fn()
    expect(authoringIssueTarget(draft,issues[0],context).targetId).toBeUndefined()
    // Even a familiar message is unresolved without its actual CSV source context.
    expect(authoringIssueTarget(draft,{line:2,message:'未知题型'}).targetId).toBeUndefined()
    render(<ResearchIssueList draft={draft} issues={issues} importContext={context} onLocate={onLocate}/>)
    expect(screen.getByText(/无法确定精确行/)).toHaveTextContent('预览数据已发生变化，请重新预览')
    expect(screen.queryByRole('button')).toBeNull();expect(onLocate).not.toHaveBeenCalled()
  })
})
